// Dedupe items by link within this batch
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const key = item.json.link || item.json.guid || JSON.stringify(item.json);
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { ...item.json, _fresh: true } });
}
console.log(`[rss] kept ${out.length} unique items`);
return out;
